// DefaultPrompt returns the standard prompt for a role, if available.
func DefaultPrompt(role string) (string, bool) {
	normalized := strings.TrimSpace(strings.ToLower(role))
	if normalized == "" {
		return "", false
	}
	prompt, ok := defaultPrompts[normalized]
	return prompt, ok
}
